excels.excel:

EXPORT WITH SHEET="票据登记台账", HEADER=true,
    MAPPING={"a":"票据号码","b":"出票日期","c":"到期日期","d":"票面金额","e":"票据期限(天)","f":"票据类型"},
    FORMAT={"b":"yyyy-MM-dd","c":"yyyy-MM-dd","d":"#,##0.00","e":"0"},
    FORMULAS={
        E2:'C2-B2',E3:'C3-B3',E4:'C4-B4',E5:'C5-B5',E6:'C6-B6',
        D7:'SUM(D2:D6)'
    },
    STYLE={ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center}}
